// Бусины мира Эноа для D&D 5e. Источник — авторский документ «Бусины Эноа».
// Бусина — магический предмет с зарядами и историей. Какая бусина попалась героям,
// определяет та же знаменная кость 4к4 (Шагай): сигнатура [Бунти, Аюр, Додор, Тахар]
// указывает на одну из 35 бусин. Редкость задаётся Сложностью опознания: 13 — необычная,
// 15 — редкая, 18 — очень редкая (четыре одинаковые грани).
//
// Заклинания записаны как «Название» (English): в 2014 они связываются со справочником
// по русскому названию, а для 2024 по этой же записи ставится ссылка в tools2024.js.
// Если название совпадает с правилом («Сопротивление»), запись оборачивается явной ссылкой.
// powers — свойства в авторском порядке: у постоянных нет cost/action, curse — цена бусины.

import { bySignature } from '../utils/shagai5e.js'

export const BEAD_TIERS = {
  uncommon: 'Необычные бусины · СЛ 13',
  rare: 'Редкие бусины · СЛ 15',
  veryRare: 'Очень редкие бусины · СЛ 18'
}

export const BEAD_TIER_LABEL = {
  uncommon: 'необычная',
  rare: 'редкая',
  veryRare: 'очень редкая'
}

function tierByDc(dc) {
  if (dc >= 18) return 'veryRare'
  if (dc >= 15) return 'rare'
  return 'uncommon'
}

function bead(num, id, title, dc, flavor, charges, powers) {
  return { num, id, title, dc, tier: tierByDc(dc), flavor: flavor.join('\n\n'), charges, powers }
}

// Постоянное свойство, активируемое свойство и цена бусины.
const trait = (name, text, extra = {}) => ({ name, text, ...extra })
const power = (name, cost, action, text, extra = {}) => ({ name, cost, action, text, ...extra })
const curse = (name, text) => ({ name, text, curse: true })

const DAWN_ALL = n => `У бусины ${n} ${n === 2 || n === 3 ? 'заряда' : 'зарядов'}. На рассвете она восстанавливает все потраченные заряды.`

